// Writes src/videos/index.ts, the list of videos Root registers: one entry per
// src/videos/<slug>/Video.tsx. Run it after adding or removing a video folder.
//
//   node scripts/register.mjs
import { existsSync, readdirSync, writeFileSync } from "node:fs";

const slugs = readdirSync("src/videos", { withFileTypes: true })
  .filter((d) => d.isDirectory() && existsSync(`src/videos/${d.name}/Video.tsx`))
  .map((d) => d.name)
  .sort();

const lines = [
  "// Generated by scripts/register.mjs; do not edit.",
  'import type { VideoDef } from "../kit";',
  ...slugs.map((slug, i) => `import { video as v${i} } from "./${slug}/Video";`),
  "",
  `export const VIDEOS: VideoDef[] = [${slugs.map((_, i) => `v${i}`).join(", ")}];`,
  "",
];
writeFileSync("src/videos/index.ts", lines.join("\n"));
console.log("registered", slugs);
